mapper.sql:
FROM sr_english_vocabulary_word w JOIN sr_english_vocabulary_theme source ON source.id=w.theme_id JOIN sr_english_vocabulary_mapping m ON m.word_id=w.id
AND w.theme_id=#{theme} AND (LOCATE(LOWER(#{search}),LOWER(w.word)) > 0 OR LOCATE(#{search},w.translation) > 0 OR LOCATE(#{search},w.scene_meaning) > 0) AND m.migration_status=#{status}
AND m.migration_status='confirmed' AND EXISTS ( SELECT 1 FROM sr_english_vocabulary_topic t JOIN sr_english_taxonomy_term n ON n.id=t.term_id LEFT JOIN sr_english_taxonomy_term parent ON parent.id=n.parent_id WHERE t.word_id=w.id AND n.enabled=1 AND (parent.id IS NULL OR parent.enabled=1) AND (n.code=#{code} OR parent.code=#{code}) AND n.library_module='vocabulary')

mapper.select:
SELECT CAST(a.id AS CHAR) id,a.title,a.slug,a.summary,a.published_at,CAST(a.keywords_json AS CHAR) keywords_json,
  (SELECT MIN(t.name) FROM sr_english_writing_article_tag r JOIN sr_english_taxonomy_term t ON t.id=r.term_id WHERE r.article_id=a.id AND t.dimension='GENRE' AND t.enabled=1) genre
 ORDER BY a.published_at DESC,a.id DESC LIMIT #{limit} OFFSET #{offset}
